branch-and-loop.cpp

  for (int column = 0; column &lt; 3; ++column) {
    std::cout &lt;&lt; column;
    if (column &lt; 2) {
      std::cout &lt;&lt; ' ';
    }
  }

类型推断
auto 不是动态类型。编译器在编译期根据初始化表达式确定类型，变量创建后仍保持该类型：


initialization-and-type-inference.cpp

#include &lt;iostream&gt;

int main() {
  int count{};
  int limit{100};
  count = 80;

  auto value = 1200;      // int
  auto ratio = 4.5;       // double
  auto enabled = true;    // bool

  value -= 100;
  std::cout &lt;&lt; "数量: " &lt;&lt; count &lt;&lt; "/" &lt;&lt; limit &lt;&lt; "\n";
  std::cout &lt;&lt; "值: " &lt;&lt; value &lt;&lt; "\n";
  std::cout &lt;&lt; "比例: " &lt;&lt; ratio &lt;&lt; "\n";
  std::cout &lt;&lt; std::boolalpha &lt;&lt; "已启用: " &lt;&lt; enabled &lt;&lt; "\n";
  return 0;
}

当右侧类型一眼可见时，auto 能减少重复，当类型本身就是接口意图时，显式写出类型更清楚。

列表推导
C++11 的 auto 与花括号组合有特殊规则。C++20 中，多个元素会推导为 std::initializer_list&lt;T&gt;，单个元素的直接列表初始化推导为该元素类型：


片段：初始化列表推导

// 片段
auto one_value{10};           // int
auto many_values{10, 20, 30}; // std::initializer_list&lt;int&gt;
auto same_type = {10, 20};    // std::initializer_list&lt;int&gt;
// auto mixed{10, 2.5};       // 编译失败：元素类型无法统一

auto 仍然需要初始化表达式。auto value; 没有推断来源，会编译失败。

片段：常量的初始化与赋值

// 片段
int current_value{12};
const int kMaxCount{5};

// kMaxCount = 6;  // 编译失败
current_value = 13; // 普通变量仍可修改

命名常量
完整示例输出两个常量的值：


const-variables.cpp

#include &lt;iostream&gt;

int main() {
  const int kMaxCount{5};
  const int kTimeoutMs{3000};

  std::cout &lt;&lt; "最大数量: " &lt;&lt; kMaxCount &lt;&lt; "\n";
  std::cout &lt;&lt; "超时毫秒数: " &lt;&lt; kTimeoutMs &lt;&lt; "\n";
  return 0;
}

项目约定常量使用 k 加大驼峰，例如 kMaxCount。名字应说明含义和单位：kTimeoutMs 的 Ms 表明单位是毫秒，使用者不必再查文档确认 3000 是秒还是毫秒。比例、时间等带单位的数值都适合把单位写进名字。

片段：编译期与运行时的分界

// 片段
int input{};
std::cin &gt;&gt; input;
const int kLimit{input};        // 运行时才知道，const 足够
constexpr int kThreshold{5000}; // 编译期确定

// constexpr int kMax{kLimit};  // 编译失败：kLimit 编译期未知




constexpr.cpp

#include &lt;iostream&gt;

constexpr bool IsInRange(int value, int low, int high) {
  return value &gt;= low && value &lt;= high;
}

int main() {
  constexpr int kThreshold{5000};
  constexpr double kRatio{0.90};

  std::cout &lt;&lt; "阈值: " &lt;&lt; kThreshold &lt;&lt; "\n";
  std::cout &lt;&lt; "比例: " &lt;&lt; kRatio &lt;&lt; "\n";
  std::cout &lt;&lt; std::boolalpha
            &lt;&lt; "4200 在区间内: " &lt;&lt; IsInRange(4200, 0, kThreshold) &lt;&lt; "\n";
  return 0;
}

头文件常量
项目公共常量通常写在头文件里，供多个 .cpp 包含。常规写法是具名命名空间加 inline constexpr：


片段：头文件中的共享常量

// 片段：board_constants.h
namespace board {
  inline constexpr int kRows{3};
  inline constexpr int kCols{3};
}
// 包含该头文件的每个 .cpp 里都写 board::kRows，
// 多份包含不会产生重复定义

命名空间的分组规则见命名空间。tictactoe::kRows 是带限定名的共享常量。命名空间作用域的 const 与 constexpr 变量默认内部链接，每个 .cpp 各有一份拷贝，通常无害但地址不共享。inline（C++17 起可用于变量）把多份拷贝合并成一个。局部 constexpr 不参与链接，不能加 inline。
推荐次序是：项目公共常量放在具名命名空间里加 inline constexpr，只在单个 .cpp 使用的常量就近放在函数内或该文件的匿名命名空间里，裸的全局常量尽量不用。
井字棋工程的行数采用同一写法，见 board.h 里的 kRows。

常量与函数
头文件里常量与函数对 inline 的要求不同。一句话规则：常量要显式 inline，函数写 constexpr 就够。









实体
